import { requireAdmin } from "../_lib/server-auth";

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // Server-side admin role check. This is the authoritative gate —
  // proxy.ts only checks "logged in", role verification happens here.
  await requireAdmin();
  return <>{children}</>;
}

