"use client";

import { useEffect } from "react";

export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error("[admin/error]", error);
  }, [error]);

  const isDev = process.env.NODE_ENV !== "production";

  return (
    <div className="flex min-h-[60vh] items-center justify-center p-8">
      <div className="max-w-lg text-center space-y-4">
        <h1 className="text-2xl font-bold">Admin panel error</h1>
        <p className="text-sm text-muted-foreground">
          {isDev
            ? error.message || "An admin tab failed to render."
            : "An admin tab failed to render. Try reloading the page."}
        </p>
        {error.digest && (
          <p className="text-xs text-muted-foreground/70 font-mono">
            Error ID: {error.digest}
          </p>
        )}
        <button
          onClick={reset}
          className="inline-block px-4 py-2 rounded-md bg-primary text-primary-foreground hover:opacity-90 transition"
        >
          Try again
        </button>
      </div>
    </div>
  );
}

