"use client";

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import {
  Users, Briefcase, FileText, Coins, DollarSign, TrendingUp, UserCheck, BarChart3,
  RefreshCw, CalendarIcon, Mail, Inbox, ArrowRight,
} from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, LineChart, Line } from "recharts";
import { format, subDays } from "date-fns";
import { cn } from "@/lib/utils";
import type { DateRange } from "react-day-picker";

interface StatsData {
  total_users: number;
  total_jobs: number;
  total_resumes: number;
  total_credits_used: number;
  total_revenue: number;
  mrr_30d: number;
  conversion_rate: number;
  active_users_7d: number;
  active_users_30d: number;
  avg_resumes_per_job: number;
  resumes_today: number;
  resumes_week: number;
  resumes_month: number;
  daily_chart: { date: string; credits: number; jobs: number; signups: number; revenue: number }[];
}

const PRESETS = [
  { label: "7 days", days: 7 },
  { label: "30 days", days: 30 },
  { label: "90 days", days: 90 },
  { label: "1 year", days: 365 },
] as const;

const DashboardTab = () => {
  const qc = useQueryClient();
  const [dateRange, setDateRange] = useState<DateRange | undefined>({
    from: subDays(new Date(), 30),
    to: new Date(),
  });
  const [activePreset, setActivePreset] = useState<number>(30);

  const fromISO = dateRange?.from?.toISOString().slice(0, 10);
  const toISO = dateRange?.to?.toISOString().slice(0, 10);

  const { data: stats, isLoading, isFetching } = useQuery({
    queryKey: ["admin_stats", fromISO, toISO],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-stats", {
        body: { from: fromISO, to: toISO },
      });
      if (error) throw error;
      return data as StatsData;
    },
  });

  const { data: emailConfig } = useQuery({
    queryKey: ["admin_email_config"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("email_ingestion_enabled").limit(1).single();
      if (error) throw error;
      return data;
    },
    staleTime: 5 * 60 * 1000,
  });

  const selectPreset = (days: number) => {
    setActivePreset(days);
    setDateRange({ from: subDays(new Date(), days), to: new Date() });
  };

  const handleRangeSelect = (range: DateRange | undefined) => {
    setDateRange(range);
    setActivePreset(0); // clear preset when custom selected
  };

  const rangeDays = dateRange?.from && dateRange?.to
    ? Math.ceil((dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24))
    : 30;
  const rangeLabel = activePreset
    ? PRESETS.find(p => p.days === activePreset)?.label ?? `${rangeDays}d`
    : dateRange?.from && dateRange?.to
      ? `${format(dateRange.from, "MMM d")} – ${format(dateRange.to, "MMM d, yyyy")}`
      : "30 days";

  const cards = [
    { label: "Total Users", value: stats?.total_users, icon: Users, color: "text-blue-500" },
    { label: "Active Users (7d)", value: stats?.active_users_7d, icon: UserCheck, color: "text-emerald-500" },
    { label: "Total Jobs", value: stats?.total_jobs, icon: Briefcase, color: "text-primary" },
    { label: "Resumes Processed", value: stats?.total_resumes, icon: FileText, color: "text-amber-500", subtitle: `Today: ${stats?.resumes_today ?? 0} · Week: ${stats?.resumes_week ?? 0}` },
    { label: "Credits Consumed", value: stats?.total_credits_used, icon: Coins, color: "text-purple-500" },
    { label: "Total Revenue", value: stats?.total_revenue != null ? `$${(stats.total_revenue / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : undefined, icon: DollarSign, color: "text-green-500", subtitle: `Period: $${((stats?.mrr_30d ?? 0) / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` },
    { label: "Conversion Rate", value: stats?.conversion_rate != null ? `${stats.conversion_rate}%` : undefined, icon: TrendingUp, color: "text-rose-500" },
    { label: "Avg Resumes/Job", value: stats?.avg_resumes_per_job, icon: BarChart3, color: "text-cyan-500" },
  ];

  const chartInterval = rangeDays > 90 ? Math.floor(rangeDays / 15) : rangeDays > 30 ? 7 : 4;

  const chartData = stats?.daily_chart?.map((d) => ({
    ...d,
    label: new Date(d.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
    revenue_dollars: d.revenue / 100,
  })) ?? [];

  const tooltipStyle = { borderRadius: 8, border: "1px solid hsl(var(--rk-border))", background: "hsl(var(--rk-card))" };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <h2 className="text-xl font-semibold">Dashboard Overview</h2>
        <div className="flex items-center gap-2 flex-wrap">
          {/* Preset buttons */}
          {PRESETS.map(({ label, days }) => (
            <Button
              key={days}
              variant={activePreset === days ? "default" : "outline"}
              size="sm"
              className="h-8 text-xs"
              onClick={() => selectPreset(days)}
            >
              {label}
            </Button>
          ))}

          {/* Custom date range picker */}
          <Popover>
            <PopoverTrigger asChild>
              <Button
                variant={activePreset === 0 ? "default" : "outline"}
                size="sm"
                className={cn("h-8 text-xs gap-1.5", activePreset === 0 && "font-medium")}
              >
                <CalendarIcon className="h-3.5 w-3.5" />
                {activePreset === 0 && dateRange?.from ? rangeLabel : "Custom"}
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="end">
              <Calendar
                mode="range"
                selected={dateRange}
                onSelect={handleRangeSelect}
                numberOfMonths={2}
                disabled={(date) => date > new Date()}
                initialFocus
                className={cn("p-3 pointer-events-auto")}
              />
            </PopoverContent>
          </Popover>

          <Button
            variant="outline"
            size="sm"
            className="h-8"
            onClick={() => qc.invalidateQueries({ queryKey: ["admin_stats", fromISO, toISO] })}
            disabled={isFetching}
          >
            <RefreshCw className={`h-3.5 w-3.5 ${isFetching ? "animate-spin" : ""}`} />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {cards.map(({ label, value, icon: Icon, color, subtitle }) => (
          <Card key={label}>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <CardTitle className="text-sm font-medium text-muted-foreground">{label}</CardTitle>
              <Icon className={`h-4 w-4 ${color}`} />
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <Skeleton className="h-8 w-20" />
              ) : (
                <>
                  <div className="text-2xl font-bold">
                    {typeof value === "string" ? value : (value?.toLocaleString() ?? 0)}
                  </div>
                  {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
                </>
              )}
            </CardContent>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Credits Usage ({rangeLabel})</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
              <ResponsiveContainer width="100%" height={220}>
                <AreaChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Area type="monotone" dataKey="credits" stroke="hsl(var(--rk-primary))" fill="hsl(var(--primary) / 0.15)" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Revenue ({rangeLabel})</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
              <ResponsiveContainer width="100%" height={220}>
                <AreaChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
                  <YAxis tick={{ fontSize: 11 }} className="text-muted-foreground" />
                  <Tooltip contentStyle={tooltipStyle} formatter={(val: number) => [`$${val.toFixed(2)}`, "Revenue"]} />
                  <Area type="monotone" dataKey="revenue_dollars" stroke="hsl(var(--rk-success))" fill="hsl(var(--rk-success) / 0.15)" strokeWidth={2} />
                </AreaChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Jobs Created ({rangeLabel})</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
              <ResponsiveContainer width="100%" height={220}>
                <BarChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Bar dataKey="jobs" fill="hsl(var(--rk-primary))" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">User Signups ({rangeLabel})</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? <Skeleton className="h-[220px] w-full" /> : (
              <ResponsiveContainer width="100%" height={220}>
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" className="stroke-border" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={chartInterval} className="text-muted-foreground" />
                  <YAxis tick={{ fontSize: 11 }} allowDecimals={false} className="text-muted-foreground" />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Line type="monotone" dataKey="signups" stroke="hsl(var(--rk-primary))" strokeWidth={2} dot={{ r: 3, fill: "hsl(var(--rk-primary))" }} />
                </LineChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Email Inbox Status Bar */}
      <div className="relative overflow-hidden rounded-xl border border-primary/20 bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 p-5">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-24 h-24 bg-primary/5 rounded-full translate-y-1/2 -translate-x-1/2" />
        <div className="relative flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-primary/15 flex items-center justify-center">
              <Inbox className="h-6 w-6 text-primary" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-semibold text-foreground">Email Ingestion</h3>
                <Badge variant={emailConfig?.email_ingestion_enabled ? "success" : "secondary"}>
                  {emailConfig?.email_ingestion_enabled ? "Active" : "Disabled"}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">
                Users can forward resumes via email to auto-collect candidates into jobs.
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className="text-right">
              <p className="text-lg font-bold text-foreground">{stats?.total_resumes ?? 0}</p>
              <p className="text-xs text-muted-foreground">Total resumes</p>
            </div>
            <div className="w-px h-8 bg-border" />
            <div className="text-right">
              <p className="text-lg font-bold text-foreground">{stats?.resumes_today ?? 0}</p>
              <p className="text-xs text-muted-foreground">Today</p>
            </div>
          </div>
        </div>
      </div>


    </div>
  );
};

export default DashboardTab;

