41	}
42	
43	const PAGE_SIZE = 25;
44	
45	const UsersTab = () => {
46	  const qc = useQueryClient();
47	  const [editUser, setEditUser] = useState<UserRow | null>(null);
48	  const [credits, setCredits] = useState("");
49	  const [bonusCredits, setBonusCredits] = useState("");
50	  const [subscriptionCredits, setSubscriptionCredits] = useState("");
51	  const [topupCredits, setTopupCredits] = useState("");
52	  const [plan, setPlan] = useState("");
53	  const [search, setSearch] = useState("");
54	  const [roleFilter, setRoleFilter] = useState<string>("all");
55	  const [planFilter, setPlanFilter] = useState<string>("all");
56	  const [activityUser, setActivityUser] = useState<UserRow | null>(null);
57	  const [page, setPage] = useState(0);
58	  const [saving, setSaving] = useState(false);
59	  const [banTarget, setBanTarget] = useState<UserRow | null>(null);
60	
61	  const { data: users, isLoading } = useQuery({
62	    queryKey: ["admin_users"],
63	    queryFn: async () => {
64	      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
65	      if (error) throw error;
66	      if (!Array.isArray(data)) {
67	        if (data?.error) throw new Error(data.error);
68	        throw new Error("Unexpected response from admin-users");
69	      }
70	      return data as UserRow[];
71	    },
72	  });
73	
74	  const { data: plans } = useQuery({
75	    queryKey: ["admin_plans"],
76	    queryFn: async () => {
77	      const { data, error } = await supabase.from("plans").select("name").order("name");
78	      if (error) throw error;
79	      return data;
80	    },
81	  });
82	
83	  const { data: activity, isLoading: activityLoading } = useQuery({
84	    queryKey: ["admin_user_activity", activityUser?.id],
85	    enabled: !!activityUser,
86	    queryFn: async () => {
87	      const { data, error } = await supabase.functions.invoke("admin-users", {
88	        body: { action: "activity", user_id: activityUser!.id },
89	      });
90	      if (error) throw error;
91	      return data as UserActivity;
92	    },
93	  });
94	
95	  const filtered = users?.filter((u) => {
96	    const matchesSearch = !search || u.email.toLowerCase().includes(search.toLowerCase());
97	    const matchesRole = roleFilter === "all" || u.role === roleFilter;
98	    const matchesPlan = planFilter === "all" || u.plan === planFilter;
99	    return matchesSearch && matchesRole && matchesPlan;
100	  }) ?? [];
101	
102	  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
103	  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
104	
105	  // Reset page when filters change
106	  const updateSearch = (v: string) => { setSearch(v); setPage(0); };
107	  const updateRoleFilter = (v: string) => { setRoleFilter(v); setPage(0); };
108	  const updatePlanFilter = (v: string) => { setPlanFilter(v); setPage(0); };
109	
110	  const openEdit = (u: UserRow) => {
111	    setEditUser(u);
112	    setCredits(String(u.credits));
113	    setSubscriptionCredits(String(u.subscription_credits));
114	    setTopupCredits(String(u.topup_credits));
115	    setBonusCredits(String(u.bonus_credits));
116	    setPlan(u.plan);
117	  };
118	
119	  const save = async () => {
120	    if (!editUser) return;
121	    setSaving(true);
122	    try {
123	      const { error } = await supabase.functions.invoke("admin-users", {
124	        body: {
125	          user_id: editUser.id,
126	          credits: parseInt(credits),
127	          subscription_credits: parseInt(subscriptionCredits),
128	          topup_credits: parseInt(topupCredits),
129	          bonus_credits: parseInt(bonusCredits),
130	          plan,
131	        },
132	      });
133	      if (error) { toast.error("Failed to update user"); return; }
134	      toast.success("User updated");
135	      logAuditAction("user.update", "user", editUser.id, {
136	        email: editUser.email,
137	        credits: parseInt(credits),
138	        subscription_credits: parseInt(subscriptionCredits),
139	        topup_credits: parseInt(topupCredits),
140	        bonus_credits: parseInt(bonusCredits),
141	        plan,
142	      });
143	      qc.invalidateQueries({ queryKey: ["admin_users"] });
144	      setEditUser(null);
145	    } finally {
146	      setSaving(false);
147	    }
148	  };
149	
150	  const confirmBan = async () => {
151	    if (!banTarget) return;
152	    const isBanned = banTarget.banned_until && new Date(banTarget.banned_until) > new Date();
153	    const { error } = await supabase.functions.invoke("admin-users", {
154	      body: { action: "ban", user_id: banTarget.id, banned: !isBanned },
155	    });
156	    if (error) { toast.error("Failed to update ban status"); return; }
157	    toast.success(isBanned ? "User unbanned" : "User banned");
158	    logAuditAction(isBanned ? "user.unban" : "user.ban", "user", banTarget.id, { email: banTarget.email });
159	    qc.invalidateQueries({ queryKey: ["admin_users"] });
160	    setBanTarget(null);
161	  };
162	
163	  const exportGDPR = async (u: UserRow) => {
164	    toast.info("Exporting user data…");
165	    const { data, error } = await supabase.functions.invoke("admin-users", {
166	      body: { action: "gdpr_export", user_id: u.id },
167	    });
168	    if (error) { toast.error("Export failed"); return; }
169	    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
170	    const url = URL.createObjectURL(blob);
171	    const a = document.createElement("a");
172	    a.href = url;
173	    a.download = `gdpr-export-${u.email}-${new Date().toISOString().slice(0, 10)}.json`;
174	    a.click();
175	    URL.revokeObjectURL(url);
176	    toast.success("GDPR export downloaded");
177	  };
178	
179	  const isBanned = (u: UserRow) => u.banned_until && new Date(u.banned_until) > new Date();
180	  const uniquePlans = [...new Set(users?.map((u) => u.plan) ?? [])];
181	
182	  return (
183	    <>
184	      <Card>
185	        <CardHeader className="pb-3">
186	          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
187	            <CardTitle className="text-lg">User Management</CardTitle>
188	            <div className="flex items-center gap-2 flex-wrap">
189	              <div className="relative">
190	                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
191	                <Input placeholder="Search email…" value={search} onChange={(e) => updateSearch(e.target.value)} className="pl-8 w-[200px]" />
192	              </div>
193	              <Select value={roleFilter} onValueChange={updateRoleFilter}>
194	                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Role" /></SelectTrigger>
195	                <SelectContent>
196	                  <SelectItem value="all">All Roles</SelectItem>
197	                  <SelectItem value="admin">Admin</SelectItem>
198	                  <SelectItem value="user">User</SelectItem>
199	                </SelectContent>
200	              </Select>
201	              <Select value={planFilter} onValueChange={updatePlanFilter}>
202	                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Plan" /></SelectTrigger>
203	                <SelectContent>
204	                  <SelectItem value="all">All Plans</SelectItem>
205	                  {uniquePlans.map((p) => <SelectItem key={p} value={p}>{p}</SelectItem>)}
206	                </SelectContent>
207	              </Select>
208	              <Badge variant="outline" className="text-xs">{filtered.length} users</Badge>
209	            </div>
210	          </div>
211	        </CardHeader>
212	        <CardContent className="p-0">
213	          <div className="overflow-x-auto">
214	            <Table>
215	              <TableHeader>
216	                <TableRow>
217	                  <TableHead>Email</TableHead>
218	                  <TableHead>Credits</TableHead>
219	                  <TableHead>Plan</TableHead>
220	                  <TableHead>Role</TableHead>
221	                  <TableHead>Status</TableHead>
222	                  <TableHead>Last Sign In</TableHead>
223	                  <TableHead>Joined</TableHead>
224	                  <TableHead className="text-right">Actions</TableHead>
225	                </TableRow>
226	              </TableHeader>
227	              <TableBody>
228	                {isLoading ? (
229	                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">Loading…</TableCell></TableRow>
230	                ) : paged.length === 0 ? (
231	                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">No users found</TableCell></TableRow>
232	                ) : paged.map((u) => (
233	                  <TableRow key={u.id} className={isBanned(u) ? "opacity-60" : ""}>
234	                    <TableCell className="font-medium">{u.email}</TableCell>
235	                    <TableCell>
236	                      <div className="flex items-center gap-1.5">
237	                        <span className="font-medium tabular-nums">{u.subscription_credits + u.topup_credits + u.bonus_credits || u.credits}</span>
238	                        {u.bonus_credits > 0 && (
239	                          <Badge variant="outline" className="text-[11px] px-1 py-0 gap-0.5">
240	                            <Gift className="h-2.5 w-2.5" />{u.bonus_credits}
241	                          </Badge>
242	                        )}
243	                      </div>
244	                    </TableCell>
245	                    <TableCell><Badge variant="secondary">{u.plan}</Badge></TableCell>
246	                    <TableCell><Badge variant={u.role === "admin" ? "default" : "outline"}>{u.role}</Badge></TableCell>
247	                    <TableCell>
248	                      {isBanned(u) ? (
249	                        <Badge variant="destructive">Banned</Badge>
250	                      ) : (
251	                        <Badge variant="outline" className="text-emerald-600 border-emerald-300 dark:text-emerald-400 dark:border-emerald-800">Active</Badge>
252	                      )}
253	                    </TableCell>
254	                    <TableCell className="text-sm text-muted-foreground">
255	                      {u.last_sign_in_at ? new Date(u.last_sign_in_at).toLocaleDateString() : "Never"}
256	                    </TableCell>
257	                    <TableCell className="text-sm">{new Date(u.created_at).toLocaleDateString()}</TableCell>
258	                    <TableCell>
259	                      <div className="flex items-center justify-end gap-1">
260	                        <Button variant="ghost" size="icon" title="View Activity" onClick={() => setActivityUser(u)}>
261	                          <Eye className="h-3.5 w-3.5" />
262	                        </Button>
263	                        <Button variant="ghost" size="icon" title="Edit" onClick={() => openEdit(u)}>
264	                          <Pencil className="h-3.5 w-3.5" />
265	                        </Button>
266	                        <Button variant="ghost" size="icon" title={isBanned(u) ? "Unban" : "Ban"} onClick={() => setBanTarget(u)}>
267	                          {isBanned(u) ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" /> : <ShieldBan className="h-3.5 w-3.5 text-destructive" />}
268	                        </Button>
269	                        <Button variant="ghost" size="icon" title="GDPR Export" onClick={() => exportGDPR(u)}>
270	                          <Download className="h-3.5 w-3.5" />
271	                        </Button>
272	                      </div>
273	                    </TableCell>
274	                  </TableRow>
275	                ))}
276	              </TableBody>
277	            </Table>
278	          </div>
279	          {totalPages > 1 && (
280	            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
281	              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
282	              <div className="flex items-center gap-2">
283	                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
284	                  <ChevronLeft className="h-3.5 w-3.5" />
285	                </Button>
286	                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
287	                  <ChevronRight className="h-3.5 w-3.5" />
288	                </Button>
289	              </div>
290	            </div>
291	          )}
292	        </CardContent>
293	      </Card>
294	
295	      {/* Edit Dialog with Plan dropdown */}
296	      <Dialog open={editUser !== null} onOpenChange={(o) => !o && setEditUser(null)}>
297	        <DialogContent>
298	          <DialogHeader><DialogTitle>Edit User: {editUser?.email}</DialogTitle></DialogHeader>
299	          <div className="space-y-3">
300	            <div className="grid grid-cols-2 gap-3">
301	              <div>
302	                <Label className="text-xs text-muted-foreground">Subscription Credits</Label>
303	                <Input type="number" value={subscriptionCredits} onChange={(e) => setSubscriptionCredits(e.target.value)} />
304	              </div>
305	              <div>
306	                <Label className="text-xs text-muted-foreground">Top-up Credits</Label>
307	                <Input type="number" value={topupCredits} onChange={(e) => setTopupCredits(e.target.value)} />
308	              </div>
309	            </div>
310	            <div className="grid grid-cols-2 gap-3">
311	              <div>
312	                <Label className="flex items-center gap-1.5 text-xs text-muted-foreground">
313	                  <Gift className="h-3 w-3" /> Bonus Credits
314	                </Label>
315	                <Input type="number" value={bonusCredits} onChange={(e) => setBonusCredits(e.target.value)} />
316	              </div>
317	              <div>
318	                <Label className="text-xs text-muted-foreground">Legacy Credits</Label>
319	                <Input type="number" value={credits} onChange={(e) => setCredits(e.target.value)} />
320	              </div>
321	            </div>
322	            <div>
323	              <Label>Plan</Label>
324	              <Select value={plan} onValueChange={setPlan}>
325	                <SelectTrigger><SelectValue placeholder="Select plan" /></SelectTrigger>
326	                <SelectContent>
327	                  <SelectItem value="free">Free</SelectItem>
328	                  {plans?.map((p) => (
329	                    <SelectItem key={p.name} value={p.name}>{p.name}</SelectItem>
330	                  ))}
331	                </SelectContent>
332	              </Select>
333	            </div>
334	            <Button onClick={save} className="w-full" disabled={saving}>
335	              {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : null}
336	              Save Changes
337	            </Button>
338	          </div>
339	        </DialogContent>
340	      </Dialog>
341	
342	      {/* Ban Confirmation */}
343	      <ConfirmDialog
344	        open={banTarget !== null}
345	        onOpenChange={(o) => !o && setBanTarget(null)}
346	        title={banTarget && isBanned(banTarget) ? "Unban User" : "Ban User"}
347	        description={
348	          banTarget && isBanned(banTarget)
349	            ? `Are you sure you want to unban ${banTarget?.email}?`
350	            : `Are you sure you want to ban ${banTarget?.email}? They will lose access to the platform.`
351	        }
352	        confirmLabel={banTarget && isBanned(banTarget) ? "Unban" : "Ban User"}
353	        variant={banTarget && isBanned(banTarget) ? "default" : "destructive"}
354	        onConfirm={confirmBan}
355	      />
356	
357	      {/* Activity Drawer */}
358	      <Sheet open={activityUser !== null} onOpenChange={(o) => !o && setActivityUser(null)}>
359	        <SheetContent className="sm:max-w-lg w-full">
360	          <SheetHeader>
361	            <SheetTitle className="text-base">{activityUser?.email}</SheetTitle>
362	          </SheetHeader>
363	          <Tabs defaultValue="jobs" className="mt-4">
364	            <TabsList className="w-full grid grid-cols-4">
365	              <TabsTrigger value="jobs">Jobs</TabsTrigger>
366	              <TabsTrigger value="resumes">Resumes</TabsTrigger>
367	              <TabsTrigger value="usage">Usage</TabsTrigger>
368	              <TabsTrigger value="payments">Payments</TabsTrigger>
369	            </TabsList>
370	            <ScrollArea className="h-[calc(100vh-180px)] mt-3">
371	              <TabsContent value="jobs" className="mt-0">
372	                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
373	                  <div className="space-y-2">
374	                    {activity?.jobs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No jobs</p>}
375	                    {activity?.jobs?.map((j) => (
376	                      <div key={j.id} className="p-3 rounded-lg border text-sm">
377	                        <div className="font-medium">{j.title || "Untitled Job"}</div>
378	                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
379	                          <Badge variant="outline" className="text-xs">{j.status}</Badge>
380	                          <span>{new Date(j.created_at).toLocaleDateString()}</span>
381	                        </div>
382	                      </div>
383	                    ))}
384	                  </div>
385	                )}
386	              </TabsContent>
387	              <TabsContent value="resumes" className="mt-0">
388	                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
389	                  <div className="space-y-2">
390	                    {activity?.resumes?.length === 0 && <p className="text-sm text-muted-foreground p-4">No resumes</p>}
391	                    {activity?.resumes?.map((r) => (
392	                      <div key={r.id} className="p-3 rounded-lg border text-sm">
393	                        <div className="font-medium truncate">{r.filename}</div>
394	                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
395	                          <Badge variant="outline" className="text-xs">{r.status}</Badge>
396	                          <span>{new Date(r.created_at).toLocaleDateString()}</span>
397	                        </div>
398	                      </div>
399	                    ))}
400	                  </div>
401	                )}
402	              </TabsContent>
403	              <TabsContent value="usage" className="mt-0">
404	                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
405	                  <div className="space-y-2">
406	                    {activity?.usage_logs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No usage</p>}
407	                    {activity?.usage_logs?.map((l) => (
408	                      <div key={l.id} className="p-3 rounded-lg border text-sm flex justify-between">
409	                        <span className="text-muted-foreground">{new Date(l.created_at).toLocaleString()}</span>
410	                        <Badge variant="secondary">{l.credits_used} credits</Badge>
411	                      </div>
412	                    ))}
413	                  </div>
414	                )}
415	              </TabsContent>
416	              <TabsContent value="payments" className="mt-0">
417	                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
418	                  <div className="space-y-2">
419	                    {activity?.payments?.length === 0 && <p className="text-sm text-muted-foreground p-4">No payments</p>}
420	                    {activity?.payments?.map((p) => (
421	                      <div key={p.id} className="p-3 rounded-lg border text-sm flex justify-between items-center">
422	                        <div>
423	                          <div className="font-medium">{p.currency} {(p.amount / 100).toFixed(2)}</div>
424	                          <div className="text-xs text-muted-foreground">{p.credits_purchased} credits · {new Date(p.created_at).toLocaleDateString()}</div>
425	                        </div>
426	                        <Badge variant={p.status === "paid" ? "default" : "outline"}>{p.status}</Badge>
427	                      </div>
428	                    ))}
429	                  </div>
430	                )}
431	              </TabsContent>
432	            </ScrollArea>
433	          </Tabs>
434	        </SheetContent>
435	      </Sheet>
436	    </>
437	  );
438	};
439	
440	export default UsersTab;
