"use client";

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Pencil, Search, Download, ShieldBan, ShieldCheck, Eye, ChevronLeft, ChevronRight, Loader2, Gift } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import ConfirmDialog from "./ConfirmDialog";
import { logAuditAction } from "@/lib/auditLog";

interface UserRow {
  id: string;
  email: string;
  credits: number;
  subscription_credits: number;
  topup_credits: number;
  bonus_credits: number;
  plan: string;
  role: string;
  created_at: string;
  last_sign_in_at: string | null;
  banned_until: string | null;
}

interface UserActivity {
  usage_logs: { id: string; credits_used: number; created_at: string; job_id: string | null }[];
  jobs: { id: string; title: string | null; status: string; created_at: string }[];
  resumes: { id: string; filename: string; status: string; created_at: string }[];
  payments: { id: string; amount: number; currency: string; status: string; credits_purchased: number; created_at: string }[];
}

const PAGE_SIZE = 25;

const UsersTab = () => {
  const qc = useQueryClient();
  const [editUser, setEditUser] = useState<UserRow | null>(null);
  const [credits, setCredits] = useState("");
  const [bonusCredits, setBonusCredits] = useState("");
  const [subscriptionCredits, setSubscriptionCredits] = useState("");
  const [topupCredits, setTopupCredits] = useState("");
  const [plan, setPlan] = useState("");
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [planFilter, setPlanFilter] = useState<string>("all");
  const [activityUser, setActivityUser] = useState<UserRow | null>(null);
  const [page, setPage] = useState(0);
  const [saving, setSaving] = useState(false);
  const [banTarget, setBanTarget] = useState<UserRow | null>(null);

  const { data: users, isLoading } = useQuery({
    queryKey: ["admin_users"],
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
      if (error) throw error;
      if (!Array.isArray(data)) {
        if (data?.error) throw new Error(data.error);
        throw new Error("Unexpected response from admin-users");
      }
      return data as UserRow[];
    },
  });

  const { data: plans } = useQuery({
    queryKey: ["admin_plans"],
    queryFn: async () => {
      const { data, error } = await supabase.from("plans").select("name").order("name");
      if (error) throw error;
      return data;
    },
  });

  const { data: activity, isLoading: activityLoading } = useQuery({
    queryKey: ["admin_user_activity", activityUser?.id],
    enabled: !!activityUser,
    queryFn: async () => {
      const { data, error } = await supabase.functions.invoke("admin-users", {
        body: { action: "activity", user_id: activityUser!.id },
      });
      if (error) throw error;
      return data as UserActivity;
    },
  });

  const filtered = users?.filter((u) => {
    const matchesSearch = !search || u.email.toLowerCase().includes(search.toLowerCase());
    const matchesRole = roleFilter === "all" || u.role === roleFilter;
    const matchesPlan = planFilter === "all" || u.plan === planFilter;
    return matchesSearch && matchesRole && matchesPlan;
  }) ?? [];

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  // Reset page when filters change
  const updateSearch = (v: string) => { setSearch(v); setPage(0); };
  const updateRoleFilter = (v: string) => { setRoleFilter(v); setPage(0); };
  const updatePlanFilter = (v: string) => { setPlanFilter(v); setPage(0); };

  const openEdit = (u: UserRow) => {
    setEditUser(u);
    setCredits(String(u.credits));
    setSubscriptionCredits(String(u.subscription_credits));
    setTopupCredits(String(u.topup_credits));
    setBonusCredits(String(u.bonus_credits));
    setPlan(u.plan);
  };

  const save = async () => {
    if (!editUser) return;
    setSaving(true);
    try {
      const { error } = await supabase.functions.invoke("admin-users", {
        body: {
          user_id: editUser.id,
          credits: parseInt(credits),
          subscription_credits: parseInt(subscriptionCredits),
          topup_credits: parseInt(topupCredits),
          bonus_credits: parseInt(bonusCredits),
          plan,
        },
      });
      if (error) { toast.error("Failed to update user"); return; }
      toast.success("User updated");
      logAuditAction("user.update", "user", editUser.id, {
        email: editUser.email,
        credits: parseInt(credits),
        subscription_credits: parseInt(subscriptionCredits),
        topup_credits: parseInt(topupCredits),
        bonus_credits: parseInt(bonusCredits),
        plan,
      });
      qc.invalidateQueries({ queryKey: ["admin_users"] });
      setEditUser(null);
    } finally {
      setSaving(false);
    }
  };

  const confirmBan = async () => {
    if (!banTarget) return;
    const isBanned = banTarget.banned_until && new Date(banTarget.banned_until) > new Date();
    const { error } = await supabase.functions.invoke("admin-users", {
      body: { action: "ban", user_id: banTarget.id, banned: !isBanned },
    });
    if (error) { toast.error("Failed to update ban status"); return; }
    toast.success(isBanned ? "User unbanned" : "User banned");
    logAuditAction(isBanned ? "user.unban" : "user.ban", "user", banTarget.id, { email: banTarget.email });
    qc.invalidateQueries({ queryKey: ["admin_users"] });
    setBanTarget(null);
  };

  const exportGDPR = async (u: UserRow) => {
    toast.info("Exporting user data…");
    const { data, error } = await supabase.functions.invoke("admin-users", {
      body: { action: "gdpr_export", user_id: u.id },
    });
    if (error) { toast.error("Export failed"); return; }
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `gdpr-export-${u.email}-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("GDPR export downloaded");
  };

  const isBanned = (u: UserRow) => u.banned_until && new Date(u.banned_until) > new Date();
  const uniquePlans = [...new Set(users?.map((u) => u.plan) ?? [])];

  return (
    <>
      <Card>
        <CardHeader className="pb-3">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <CardTitle className="text-lg">User Management</CardTitle>
            <div className="flex items-center gap-2 flex-wrap">
              <div className="relative">
                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input placeholder="Search email…" value={search} onChange={(e) => updateSearch(e.target.value)} className="pl-8 w-[200px]" />
              </div>
              <Select value={roleFilter} onValueChange={updateRoleFilter}>
                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Role" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Roles</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="user">User</SelectItem>
                </SelectContent>
              </Select>
              <Select value={planFilter} onValueChange={updatePlanFilter}>
                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Plan" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Plans</SelectItem>
                  {uniquePlans.map((p) => <SelectItem key={p} value={p}>{p}</SelectItem>)}
                </SelectContent>
              </Select>
              <Badge variant="outline" className="text-xs">{filtered.length} users</Badge>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Email</TableHead>
                  <TableHead>Credits</TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Last Sign In</TableHead>
                  <TableHead>Joined</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">Loading…</TableCell></TableRow>
                ) : paged.length === 0 ? (
                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">No users found</TableCell></TableRow>
                ) : paged.map((u) => (
                  <TableRow key={u.id} className={isBanned(u) ? "opacity-60" : ""}>
                    <TableCell className="font-medium">{u.email}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1.5">
                        <span className="font-medium tabular-nums">{u.subscription_credits + u.topup_credits + u.bonus_credits || u.credits}</span>
                        {u.bonus_credits > 0 && (
                          <Badge variant="outline" className="text-[11px] px-1 py-0 gap-0.5">
                            <Gift className="h-2.5 w-2.5" />{u.bonus_credits}
                          </Badge>
                        )}
                      </div>
                    </TableCell>
                    <TableCell><Badge variant="secondary">{u.plan}</Badge></TableCell>
                    <TableCell><Badge variant={u.role === "admin" ? "default" : "outline"}>{u.role}</Badge></TableCell>
                    <TableCell>
                      {isBanned(u) ? (
                        <Badge variant="destructive">Banned</Badge>
                      ) : (
                        <Badge variant="outline" className="text-emerald-600 border-emerald-300 dark:text-emerald-400 dark:border-emerald-800">Active</Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-sm text-muted-foreground">
                      {u.last_sign_in_at ? new Date(u.last_sign_in_at).toLocaleDateString() : "Never"}
                    </TableCell>
                    <TableCell className="text-sm">{new Date(u.created_at).toLocaleDateString()}</TableCell>
                    <TableCell>
                      <div className="flex items-center justify-end gap-1">
                        <Button variant="ghost" size="icon" title="View Activity" onClick={() => setActivityUser(u)}>
                          <Eye className="h-3.5 w-3.5" />
                        </Button>
                        <Button variant="ghost" size="icon" title="Edit" onClick={() => openEdit(u)}>
                          <Pencil className="h-3.5 w-3.5" />
                        </Button>
                        <Button variant="ghost" size="icon" title={isBanned(u) ? "Unban" : "Ban"} onClick={() => setBanTarget(u)}>
                          {isBanned(u) ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" /> : <ShieldBan className="h-3.5 w-3.5 text-destructive" />}
                        </Button>
                        <Button variant="ghost" size="icon" title="GDPR Export" onClick={() => exportGDPR(u)}>
                          <Download className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
              <div className="flex items-center gap-2">
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
                  <ChevronLeft className="h-3.5 w-3.5" />
                </Button>
                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
                  <ChevronRight className="h-3.5 w-3.5" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Edit Dialog with Plan dropdown */}
      <Dialog open={editUser !== null} onOpenChange={(o) => !o && setEditUser(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle>Edit User: {editUser?.email}</DialogTitle></DialogHeader>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-xs text-muted-foreground">Subscription Credits</Label>
                <Input type="number" value={subscriptionCredits} onChange={(e) => setSubscriptionCredits(e.target.value)} />
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Top-up Credits</Label>
                <Input type="number" value={topupCredits} onChange={(e) => setTopupCredits(e.target.value)} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <Gift className="h-3 w-3" /> Bonus Credits
                </Label>
                <Input type="number" value={bonusCredits} onChange={(e) => setBonusCredits(e.target.value)} />
              </div>
              <div>
                <Label className="text-xs text-muted-foreground">Legacy Credits</Label>
                <Input type="number" value={credits} onChange={(e) => setCredits(e.target.value)} />
              </div>
            </div>
            <div>
              <Label>Plan</Label>
              <Select value={plan} onValueChange={setPlan}>
                <SelectTrigger><SelectValue placeholder="Select plan" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="free">Free</SelectItem>
                  {plans?.map((p) => (
                    <SelectItem key={p.name} value={p.name}>{p.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button onClick={save} className="w-full" disabled={saving}>
              {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : null}
              Save Changes
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Ban Confirmation */}
      <ConfirmDialog
        open={banTarget !== null}
        onOpenChange={(o) => !o && setBanTarget(null)}
        title={banTarget && isBanned(banTarget) ? "Unban User" : "Ban User"}
        description={
          banTarget && isBanned(banTarget)
            ? `Are you sure you want to unban ${banTarget?.email}?`
            : `Are you sure you want to ban ${banTarget?.email}? They will lose access to the platform.`
        }
        confirmLabel={banTarget && isBanned(banTarget) ? "Unban" : "Ban User"}
        variant={banTarget && isBanned(banTarget) ? "default" : "destructive"}
        onConfirm={confirmBan}
      />

      {/* Activity Drawer */}
      <Sheet open={activityUser !== null} onOpenChange={(o) => !o && setActivityUser(null)}>
        <SheetContent className="sm:max-w-lg w-full">
          <SheetHeader>
            <SheetTitle className="text-base">{activityUser?.email}</SheetTitle>
          </SheetHeader>
          <Tabs defaultValue="jobs" className="mt-4">
            <TabsList className="w-full grid grid-cols-4">
              <TabsTrigger value="jobs">Jobs</TabsTrigger>
              <TabsTrigger value="resumes">Resumes</TabsTrigger>
              <TabsTrigger value="usage">Usage</TabsTrigger>
              <TabsTrigger value="payments">Payments</TabsTrigger>
            </TabsList>
            <ScrollArea className="h-[calc(100vh-180px)] mt-3">
              <TabsContent value="jobs" className="mt-0">
                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
                  <div className="space-y-2">
                    {activity?.jobs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No jobs</p>}
                    {activity?.jobs?.map((j) => (
                      <div key={j.id} className="p-3 rounded-lg border text-sm">
                        <div className="font-medium">{j.title || "Untitled Job"}</div>
                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
                          <Badge variant="outline" className="text-xs">{j.status}</Badge>
                          <span>{new Date(j.created_at).toLocaleDateString()}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
              <TabsContent value="resumes" className="mt-0">
                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
                  <div className="space-y-2">
                    {activity?.resumes?.length === 0 && <p className="text-sm text-muted-foreground p-4">No resumes</p>}
                    {activity?.resumes?.map((r) => (
                      <div key={r.id} className="p-3 rounded-lg border text-sm">
                        <div className="font-medium truncate">{r.filename}</div>
                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
                          <Badge variant="outline" className="text-xs">{r.status}</Badge>
                          <span>{new Date(r.created_at).toLocaleDateString()}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
              <TabsContent value="usage" className="mt-0">
                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
                  <div className="space-y-2">
                    {activity?.usage_logs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No usage</p>}
                    {activity?.usage_logs?.map((l) => (
                      <div key={l.id} className="p-3 rounded-lg border text-sm flex justify-between">
                        <span className="text-muted-foreground">{new Date(l.created_at).toLocaleString()}</span>
                        <Badge variant="secondary">{l.credits_used} credits</Badge>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
              <TabsContent value="payments" className="mt-0">
                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
                  <div className="space-y-2">
                    {activity?.payments?.length === 0 && <p className="text-sm text-muted-foreground p-4">No payments</p>}
                    {activity?.payments?.map((p) => (
                      <div key={p.id} className="p-3 rounded-lg border text-sm flex justify-between items-center">
                        <div>
                          <div className="font-medium">{p.currency} {(p.amount / 100).toFixed(2)}</div>
                          <div className="text-xs text-muted-foreground">{p.credits_purchased} credits · {new Date(p.created_at).toLocaleDateString()}</div>
                        </div>
                        <Badge variant={p.status === "paid" ? "default" : "outline"}>{p.status}</Badge>
                      </div>
                    ))}
                  </div>
                )}
              </TabsContent>
            </ScrollArea>
          </Tabs>
        </SheetContent>
      </Sheet>
    </>
  );
};

export default UsersTab;

