"use client";

import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Loader2, RefreshCw, CheckCircle, Store } from "lucide-react";
import PlansTab from "./PlansTab";
import PaymentsTab from "./PaymentsTab";
import SubscriptionsSubTab from "./SubscriptionsSubTab";

const BillingTab = () => {
  const qc = useQueryClient();
  const [fetchingBrands, setFetchingBrands] = useState(false);
  const [brands, setBrands] = useState<any[] | null>(null);
  const [savingBrand, setSavingBrand] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["platform_config_brand"],
    queryFn: async () => {
      const { data, error } = await supabase.from("platform_config").select("dodo_brand_id").limit(1).single();
      if (error) return null;
      return data;
    },
  });

  const fetchBrands = async () => {
    setFetchingBrands(true);
    try {
      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
        body: { action: "fetch_brands" },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      const brandList = Array.isArray(data?.brands) ? data.brands : data?.brands?.items || [];
      setBrands(brandList);
      if (brandList.length === 0) toast.info("No brands found on Dodo. Create one in Dodo Dashboard first.");
    } catch (err: any) {
      toast.error("Failed to fetch brands: " + (err.message || "Unknown error"));
    } finally {
      setFetchingBrands(false);
    }
  };

  const saveBrandId = async (brandId: string) => {
    setSavingBrand(true);
    try {
      const { error } = await supabase.from("platform_config").update({ dodo_brand_id: brandId } as any).not("id", "is", null);
      if (error) throw error;
      toast.success("Dodo brand saved ✓");
      qc.invalidateQueries({ queryKey: ["platform_config_brand"] });
    } catch (err: any) {
      toast.error("Failed to save brand: " + (err.message || "Unknown error"));
    } finally {
      setSavingBrand(false);
    }
  };

  return (
    <div className="space-y-4">
      <h2 className="text-xl font-semibold">Billing & Plans</h2>

      {/* Dodo Brand Config */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center gap-2">
            <Store className="h-4 w-4 text-primary" />
            Dodo Brand
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-3 flex-wrap">
            {config?.dodo_brand_id ? (
              <div className="flex items-center gap-2">
                <Badge variant="secondary" className="gap-1 text-xs">
                  <CheckCircle className="h-3 w-3 text-emerald-600" />
                  {config.dodo_brand_id}
                </Badge>
                <span className="text-xs text-muted-foreground">All products auto-attach this brand</span>
              </div>
            ) : (
              <span className="text-sm text-muted-foreground">No brand configured — products will be created without a brand.</span>
            )}
            <Button variant="outline" size="sm" onClick={fetchBrands} disabled={fetchingBrands}>
              {fetchingBrands ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <RefreshCw className="h-3.5 w-3.5 mr-1" />}
              Fetch Brands
            </Button>
          </div>

          {brands && brands.length > 0 && (
            <div className="mt-3 flex flex-wrap gap-2">
              {brands.map((b: any) => (
                <Button
                  key={b.id || b.brand_id}
                  variant={config?.dodo_brand_id === (b.id || b.brand_id) ? "default" : "outline"}
                  size="sm"
                  className="text-xs"
                  disabled={savingBrand}
                  onClick={() => saveBrandId(b.id || b.brand_id)}
                >
                  {b.name || b.id || b.brand_id}
                </Button>
              ))}
            </div>
          )}

          {brands && brands.length === 0 && (
            <div className="mt-2">
              <p className="text-xs text-muted-foreground">No brands found. You can manually enter a brand ID:</p>
              <div className="flex gap-2 mt-1">
                <Input
                  placeholder="Brand ID from Dodo Dashboard"
                  className="max-w-xs text-xs"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      const val = (e.target as HTMLInputElement).value.trim();
                      if (val) saveBrandId(val);
                    }
                  }}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <Tabs defaultValue="plans">
        <TabsList>
          <TabsTrigger value="plans">Plans</TabsTrigger>
          <TabsTrigger value="payments">Payments</TabsTrigger>
          <TabsTrigger value="subscriptions">Subscriptions</TabsTrigger>
        </TabsList>
        <TabsContent value="plans"><PlansTab /></TabsContent>
        <TabsContent value="payments"><PaymentsTab /></TabsContent>
        <TabsContent value="subscriptions"><SubscriptionsSubTab /></TabsContent>
      </Tabs>
    </div>
  );
};

export default BillingTab;

