  ai: "text-purple-600 border-purple-300 dark:text-purple-400 dark:border-purple-700",
  general: "text-muted-foreground",
};

const FeatureFlagsTab = () => {
  const qc = useQueryClient();
  const [editFlag, setEditFlag] = useState<FeatureFlag | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [form, setForm] = useState({ key: "", label: "", description: "", category: "general", value_json: "{}" });
  const [filterCategory, setFilterCategory] = useState("all");

  const { data: flags, isLoading } = useQuery({
    queryKey: ["feature_flags"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("feature_flags")
        .select("*")
        .order("category")
        .order("key");
      if (error) throw error;
      return data as FeatureFlag[];
