import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { Plus, Pencil, Trash2, Flag } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

interface FeatureFlag {
  id: string;
  key: string;
  name: string;
  description: string;
  enabled: boolean;
  value_json: Record<string, unknown> | null;
  created_at: string;
  updated_at: string;
}

const FeatureFlagsTab = () => {
  const qc = useQueryClient();
  const [editFlag, setEditFlag] = useState<FeatureFlag | null>(null);
  const [isNew, setIsNew] = useState(false);
  const [form, setForm] = useState({ key: "", name: "", description: "", value_json: "{}" });

  const { data: flags, isLoading } = useQuery({
    queryKey: ["feature_flags"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("feature_flags")
        .select("*")
        .order("key");
      if (error) throw error;
      return data as unknown as FeatureFlag[];
    },
  });

  const allFlags = flags ?? [];

  const toggleFlag = async (flag: FeatureFlag) => {
    const { error } = await supabase
      .from("feature_flags")
      .update({ enabled: !flag.enabled } as any)
      .eq("id", flag.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`${flag.name} ${!flag.enabled ? "enabled" : "disabled"}`);
    logAuditAction("feature_flag.toggle", "feature_flag", flag.id, { key: flag.key, enabled: !flag.enabled });
    qc.invalidateQueries({ queryKey: ["feature_flags"] });
  };

  const openNew = () => {
    setIsNew(true);
    setForm({ key: "", name: "", description: "", value_json: "{}" });
    setEditFlag({} as FeatureFlag);
  };

  const openEdit = (f: FeatureFlag) => {
    setIsNew(false);
    setForm({
      key: f.key,
      name: f.name,
      description: f.description,
      value_json: JSON.stringify(f.value_json ?? {}, null, 2),
    });
    setEditFlag(f);
  };

  const save = async () => {
    if (!form.key || !form.name) { toast.error("Key and name are required"); return; }
    let parsedJson: Record<string, unknown>;
    try {
      parsedJson = JSON.parse(form.value_json) as Record<string, unknown>;
    } catch {
      toast.error("Invalid JSON in value field");
      return;
    }

    const payload = {
      key: form.key,
      name: form.name,
      description: form.description,
      value_json: parsedJson,
    };

    if (isNew) {
      const { error } = await supabase.from("feature_flags").insert(payload);
      if (error) { toast.error(error.message); return; }
      toast.success("Flag created");
      logAuditAction("feature_flag.create", "feature_flag", undefined, { key: form.key, name: form.name });
    } else {
      const { error } = await supabase.from("feature_flags").update(payload).eq("id", editFlag!.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Flag updated");
      logAuditAction("feature_flag.update", "feature_flag", editFlag!.id, { key: form.key, name: form.name });
    }
    qc.invalidateQueries({ queryKey: ["feature_flags"] });
    setEditFlag(null);
  };

  const deleteFlag = async (f: FeatureFlag) => {
    if (!confirm(`Delete flag "${f.name}"?`)) return;
    const { error } = await supabase.from("feature_flags").delete().eq("id", f.id);
    if (error) { toast.error(error.message); return; }
    toast.success("Flag deleted");
    logAuditAction("feature_flag.delete", "feature_flag", f.id, { key: f.key, name: f.name });
    qc.invalidateQueries({ queryKey: ["feature_flags"] });
  };

  return (
    <>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold flex items-center gap-2">
            <Flag className="h-5 w-5" /> Feature Flags
          </h2>
          <div className="flex items-center gap-2">
            <Select value={filterCategory} onValueChange={setFilterCategory}>
              <SelectTrigger className="w-[140px]"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Categories</SelectItem>
                {CATEGORIES.map((c) => <SelectItem key={c} value={c} className="capitalize">{c}</SelectItem>)}
              </SelectContent>
            </Select>
            <Button onClick={openNew} size="sm"><Plus className="h-4 w-4 mr-1" />Add Flag</Button>
          </div>
        </div>

        {isLoading ? (
          <p className="text-muted-foreground text-sm">Loading…</p>
        ) : Object.entries(grouped).length === 0 ? (
          <p className="text-muted-foreground text-sm">No feature flags found.</p>
        ) : (
          Object.entries(grouped).map(([category, categoryFlags]) => (
            <div key={category} className="space-y-3">
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wider">{category}</h3>
              <div className="grid gap-3">
                {categoryFlags.map((f) => (
                  <Card key={f.id}>
                    <CardContent className="flex items-center justify-between p-4">
                      <div className="flex-1 min-w-0 mr-4">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="font-medium text-sm">{f.label}</span>
                          <Badge variant="outline" className={`text-xs ${categoryColors[f.category] ?? ""}`}>
                            {f.category}
                          </Badge>
                          <code className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded">{f.key}</code>
                        </div>
                        {f.description && <p className="text-xs text-muted-foreground">{f.description}</p>}
                        {Object.keys(f.value_json ?? {}).length > 0 && (
                          <code className="text-xs text-muted-foreground mt-1 block">
                            {JSON.stringify(f.value_json)}
                          </code>
                        )}
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        <Switch checked={f.enabled} onCheckedChange={() => toggleFlag(f)} />
                        <Button variant="ghost" size="icon" onClick={() => openEdit(f)}>
                          <Pencil className="h-3.5 w-3.5" />
                        </Button>
                        <Button variant="ghost" size="icon" onClick={() => deleteFlag(f)}>
                          <Trash2 className="h-3.5 w-3.5 text-destructive" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Create / Edit Dialog */}
      <Dialog open={editFlag !== null} onOpenChange={(o) => !o && setEditFlag(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{isNew ? "Create Feature Flag" : "Edit Feature Flag"}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label>Key (unique identifier)</Label>
              <Input value={form.key} onChange={(e) => setForm({ ...form, key: e.target.value })} placeholder="e.g. dark_mode" disabled={!isNew} />
            </div>
            <div>
              <Label>Label</Label>
              <Input value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} placeholder="e.g. Dark Mode" />
            </div>
            <div>
              <Label>Description</Label>
              <Input value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Optional description" />
            </div>
            <div>
              <Label>Category</Label>
              <Select value={form.category} onValueChange={(v) => setForm({ ...form, category: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {CATEGORIES.map((c) => <SelectItem key={c} value={c} className="capitalize">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Value (JSON)</Label>
              <Textarea
                value={form.value_json}
                onChange={(e) => setForm({ ...form, value_json: e.target.value })}
                rows={4}
                className="font-mono text-xs"
                placeholder='{"limit": 10}'
              />
            </div>
            <Button onClick={save} className="w-full">{isNew ? "Create Flag" : "Save Changes"}</Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default FeatureFlagsTab;

