"use client";

import { useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import DOMPurify from "dompurify";
import { supabase } from "@/integrations/supabase/client";

const ChatWidget = () => {
  const { data } = useQuery({
    queryKey: ["chat_widget_config"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("chat_widget_enabled, chat_widget_code")
        .limit(1)
        .single();
      if (error) return null;
      return data as { chat_widget_enabled: boolean; chat_widget_code: string } | null;
    },
    staleTime: 5 * 60 * 1000,
  });

  useEffect(() => {
    const containerId = "rankora-chat-widget";

    // Clean up any previous widget
    const existing = document.getElementById(containerId);
    if (existing) existing.remove();

    if (!data?.chat_widget_enabled || !data?.chat_widget_code?.trim()) return;

    // Create a container and inject the embed code
    const container = document.createElement("div");
    container.id = containerId;
    document.body.appendChild(container);

    // Sanitize embed code — allow external scripts (src-based) but strip inline script content
    const sanitized = DOMPurify.sanitize(data.chat_widget_code, {
      ADD_TAGS: ["script", "iframe"],
      ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
      FORCE_BODY: true,
    });

    // Parse and execute scripts from the sanitized embed code
    const temp = document.createElement("div");
    temp.innerHTML = sanitized;

    // Move non-script nodes and re-create script tags to execute them
    Array.from(temp.childNodes).forEach((node) => {
      if (node instanceof HTMLScriptElement) {
        const script = document.createElement("script");
        // Only allow scripts with external src — strip inline script content for safety
        if (node.src) {
          script.src = node.src;
          if (node.async) script.async = true;
          if (node.defer) script.defer = true;
          Array.from(node.attributes).forEach((attr) => {
            if (!["src", "async", "defer"].includes(attr.name)) {
              script.setAttribute(attr.name, attr.value);
            }
          });
          container.appendChild(script);
        }
      } else {
        container.appendChild(node.cloneNode(true));
      }
    });

    return () => {
      const el = document.getElementById(containerId);
      if (el) el.remove();
    };
  }, [data?.chat_widget_enabled, data?.chat_widget_code]);

  return null;
};

export default ChatWidget;

