const handleVerify = async (planId: string, productId: string) => {
  setVerifying(productId);
  try {
    const result = await syncDodoProduct("verify", { product_id: productId });
    setVerifyResults(prev => ({ ...prev, [productId]: result }));
    if (result.exists && result.is_active) {
      toast.success("Product verified on Dodo ✓");
    } else if (result.exists && !result.is_active) {
      toast.warning("Product exists on Dodo but is archived/inactive");
    } else {
      await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", planId);
      qc.invalidateQueries({ queryKey: ["admin_plans"] });
      toast.error("Product not found on Dodo — link cleared automatically");
    }
  } catch (err: any) {
    toast.error("Verify failed: " + (err.message || "Unknown error"));
  } finally {
    setVerifying(null);
  }
};

const handleSyncToDodo = async (plan: any) => {
  setSaving(true);
  try {
    const dodoResult = await syncDodoProduct("create", {
      name: plan.name,
      price: plan.price,
      credits: plan.credits,
      billing_type: plan.billing_type,
      description: plan.description || "",
    });
    if (dodoResult.product_id) {
      const updateData: any = { dodo_product_id: dodoResult.product_id };
      if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
      await supabase.from("plans").update(updateData).eq("id", plan.id);
      toast.success("Plan synced with Dodo ✓");
      qc.invalidateQueries({ queryKey: ["admin_plans"] });
    }
  } catch (err: any) {
    toast.error("Dodo sync failed: " + (err.message || "Unknown error"));
  } finally {
    setSaving(false);
  }
};

