const DodoCard = ({ integration, config, onTest, testing, onConfigSaved }: any) => {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const dodoCfg = (integration?.config_json ?? {}) as Record<string, unknown>;
  const [environment, setEnvironment] = useState<string>((dodoCfg.environment as string) || "test_mode");

  const envChanged = environment !== ((dodoCfg.environment as string) || "test_mode");

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await (supabase.from as Function)("integrations")
        .upsert({
          key_name: "DODO_PAYMENTS_API_KEY",
          config_json: { environment },
          display_name: "Dodo Payments",
          description: "Payment processing via Dodo",
        }, { onConflict: "key_name" });
      if (error) throw error;
      toast.success("Dodo environment updated");
      logAuditAction("integration.update", "integrations", "DODO_PAYMENTS_API_KEY", { integration: "dodo", environment });
      onConfigSaved?.();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Save failed";
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  };

