"use client";

import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoSettings } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { Save, Loader2, Share2 } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const SocialMediaTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const [form, setForm] = useState({
    og_title: "",
    og_description: "",
    og_image_url: "",
    og_type: "website",
    og_site_name: "",
    twitter_card: "summary_large_image",
    twitter_site: "",
    twitter_creator: "",
    twitter_image_url: "",
  });

  if (settings && !loaded) {
    setForm({
      og_title: settings.og_title ?? "",
      og_description: settings.og_description ?? "",
      og_image_url: settings.og_image_url ?? "",
      og_type: settings.og_type ?? "website",
      og_site_name: settings.og_site_name ?? "",
      twitter_card: settings.twitter_card ?? "summary_large_image",
      twitter_site: settings.twitter_site ?? "",
      twitter_creator: settings.twitter_creator ?? "",
      twitter_image_url: settings.twitter_image_url ?? "",
    });
    setLoaded(true);
  }

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from("seo_settings")
        .update(form)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Social media settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "social", ...form });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2"><Share2 className="h-5 w-5" /> Open Graph (Facebook, LinkedIn, etc.)</CardTitle>
          <CardDescription>Controls how your site appears when shared on social media. Falls back to global meta if empty.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label>OG Title</Label>
              <Input value={form.og_title} onChange={(e) => setForm({ ...form, og_title: e.target.value })} placeholder="Leave empty to use Site Title" />
            </div>
            <div>
              <Label>OG Site Name</Label>
              <Input value={form.og_site_name} onChange={(e) => setForm({ ...form, og_site_name: e.target.value })} placeholder="Rankora" />
            </div>
            <div className="sm:col-span-2">
              <Label>OG Description</Label>
              <Input value={form.og_description} onChange={(e) => setForm({ ...form, og_description: e.target.value })} placeholder="Leave empty to use Site Description" />
            </div>
            <div>
              <Label>OG Image URL</Label>
              <Input value={form.og_image_url} onChange={(e) => setForm({ ...form, og_image_url: e.target.value })} placeholder="https://yourdomain.com/og-image.png" />
              <p className="text-xs text-muted-foreground mt-1">Recommended: 1200x630px</p>
            </div>
            <div>
              <Label>OG Type</Label>
              <Select value={form.og_type} onValueChange={(v) => setForm({ ...form, og_type: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="website">website</SelectItem>
                  <SelectItem value="article">article</SelectItem>
                  <SelectItem value="product">product</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg">Twitter Card</CardTitle>
          <CardDescription>Controls how your site appears when shared on Twitter/X.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label>Card Type</Label>
              <Select value={form.twitter_card} onValueChange={(v) => setForm({ ...form, twitter_card: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="summary">summary</SelectItem>
                  <SelectItem value="summary_large_image">summary_large_image</SelectItem>
                  <SelectItem value="app">app</SelectItem>
                  <SelectItem value="player">player</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Twitter @site</Label>
              <Input value={form.twitter_site} onChange={(e) => setForm({ ...form, twitter_site: e.target.value })} placeholder="@yourbrand" />
            </div>
            <div>
              <Label>Twitter @creator</Label>
              <Input value={form.twitter_creator} onChange={(e) => setForm({ ...form, twitter_creator: e.target.value })} placeholder="@yourcreator" />
            </div>
            <div>
              <Label>Twitter Image URL</Label>
              <Input value={form.twitter_image_url} onChange={(e) => setForm({ ...form, twitter_image_url: e.target.value })} placeholder="Leave empty to use OG Image" />
            </div>
          </div>
        </CardContent>
      </Card>

      {(form.og_image_url || form.twitter_image_url) && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg">Preview</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="border rounded-lg overflow-hidden max-w-md">
              {(form.og_image_url || form.twitter_image_url) && (
                <img src={form.og_image_url || form.twitter_image_url} alt="Social preview" className="w-full h-40 object-cover bg-muted" onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }} />
              )}
              <div className="p-3">
                <p className="font-semibold text-sm">{form.og_title || settings?.site_title || "Site Title"}</p>
                <p className="text-xs text-muted-foreground mt-1">{form.og_description || settings?.site_description || "Site description..."}</p>
                <p className="text-xs text-muted-foreground mt-1">{form.og_site_name || "yourdomain.com"}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save Social Media Settings
      </Button>
    </div>
  );
};

export default SocialMediaTab;

