const toggleResolved = async (id: string, currentlyResolved: boolean) => {
  const { error } = await supabase
    .from("system_error_logs")
    .update({
      is_resolved: !currentlyResolved,
      resolved_at: !currentlyResolved ? new Date().toISOString() : null,
    })
    .eq("id", id);
  if (error) { toast.error(error.message); return; }
  toast.success(currentlyResolved ? "Marked as unresolved" : "Marked as resolved");
  qc.invalidateQueries({ queryKey: ["system_error_logs"] });
};

