"use client";

import { useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface SeoSettings {
  id: string;
  site_title: string | null;
  site_description: string | null;
  site_keywords: string | null;
  canonical_url: string | null;
  og_title: string | null;
  og_description: string | null;
  og_image_url: string | null;
  og_type: string | null;
  og_site_name: string | null;
  twitter_card: string | null;
  twitter_site: string | null;
  twitter_creator: string | null;
  meta_robots: string | null;
  google_analytics_id: string | null;
  google_site_verification: string | null;
  bing_site_verification: string | null;
  facebook_domain_verification: string | null;
  theme_color: string | null;
  structured_data_json: Record<string, unknown> | null;
  updated_at: string | null;
}

export interface SeoPage {
  id: string;
  page_path: string;
  title: string | null;
  description: string | null;
  keywords: string | null;
  og_title: string | null;
  og_description: string | null;
  og_image_url: string | null;
  meta_robots: string | null;
  canonical_url: string | null;
  structured_data_json: Record<string, unknown> | null;
  is_active: boolean | null;
  created_at: string | null;
  updated_at: string | null;
}

export function useSeoSettings() {
  const qc = useQueryClient();

  const { data: settings, isLoading } = useQuery({
    queryKey: ["seo_settings"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("seo_settings")
        .select("*")
        .limit(1)
        .single();
      if (error) throw error;
      return data as unknown as SeoSettings;
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    const channel = supabase
      .channel("seo_settings_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "seo_settings" },
        () => {
          qc.invalidateQueries({ queryKey: ["seo_settings"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [qc]);

  return { settings, isLoading };
}

export function useSeoPages() {
  const qc = useQueryClient();

  const { data: pages, isLoading } = useQuery({
    queryKey: ["seo_pages"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("seo_pages")
        .select("*")
        .order("page_path");
      if (error) throw error;
      return data as unknown as SeoPage[];
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    const channel = supabase
      .channel("seo_pages_realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "seo_pages" },
        () => {
          qc.invalidateQueries({ queryKey: ["seo_pages"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [qc]);

  return { pages: pages ?? [], isLoading };
}

export function useSeoPageByPath(path: string) {
  const { pages, isLoading } = useSeoPages();
  const page = pages.find((p) => p.page_path === path);
  return { page, isLoading };
}

