toolUseResult.originalFile:
"use client";

import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoPages, type SeoPage } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { toast } from "sonner";
import { Save, Loader2, FileText, Plus, Pencil, Trash2 } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const emptyPage: Omit<SeoPage, "id" | "created_at" | "updated_at"> = {
  page_path: "",
  title: "",
  description: "",
  keywords: "",
  og_title: "",
  og_description: "",
  og_image_url: "",
  meta_robots: "",
  canonical_url: "",
  structured_data_json: {},
  is_active: true,
};

const PageSeoTab = () => {
  const qc = useQueryClient();
  const { pages, isLoading } = useSeoPages();
  const [saving, setSaving] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingPage, setEditingPage] = useState<SeoPage | null>(null);
  const [form, setForm] = useState(emptyPage);

  const openCreate = () => {
    setEditingPage(null);
    setForm({ ...emptyPage });
    setDialogOpen(true);
  };

  const openEdit = (page: SeoPage) => {
    setEditingPage(page);
    setForm({
      page_path: page.page_path,
      title: page.title ?? "",
      description: page.description ?? "",
      keywords: page.keywords ?? "",
      og_title: page.og_title ?? "",
      og_description: page.og_description ?? "",
      og_image_url: page.og_image_url ?? "",
      meta_robots: page.meta_robots ?? "",
      canonical_url: page.canonical_url ?? "",
      structured_data_json: page.structured_data_json ?? {},
      is_active: page.is_active ?? true,
    });
    setDialogOpen(true);
  };

  const savePage = async () => {
    if (!form.page_path.trim()) { toast.error("Page path is required"); return; }
    if (!form.page_path.startsWith("/")) { toast.error("Page path must start with /"); return; }
    setSaving(true);
    try {
      if (editingPage) {
        const { error } = await supabase
          .from("seo_pages")
          .update(form)
          .eq("id", editingPage.id);
        if (error) { toast.error(error.message); return; }
        toast.success("Page SEO updated");
        logAuditAction("seo_page.update", "seo_pages", editingPage.id, { page_path: form.page_path });
      } else {
        const { error } = await supabase
          .from("seo_pages")
          .insert(form);
        if (error) { toast.error(error.message); return; }
        toast.success("Page SEO created");
        logAuditAction("seo_page.create", "seo_pages", undefined, { page_path: form.page_path });
      }
      qc.invalidateQueries({ queryKey: ["seo_pages"] });
      setDialogOpen(false);
    } finally {
      setSaving(false);
    }
  };

  const deletePage = async (page: SeoPage) => {
    if (!confirm(`Delete SEO settings for "${page.page_path}"?`)) return;
    const { error } = await supabase.from("seo_pages").delete().eq("id", page.id);
    if (error) { toast.error(error.message); return; }
    toast.success("Page SEO deleted");
    logAuditAction("seo_page.delete", "seo_pages", page.id, { page_path: page.page_path });
    qc.invalidateQueries({ queryKey: ["seo_pages"] });
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg flex items-center gap-2"><FileText className="h-5 w-5" /> Per-Page SEO</CardTitle>
              <CardDescription>Override global SEO settings for individual pages. Empty fields inherit from global settings.</CardDescription>
            </div>
            <Button size="sm" onClick={openCreate}>
              <Plus className="h-3 w-3 mr-1" /> Add Page
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {pages.length === 0 ? (
            <p className="text-sm text-muted-foreground">No page-specific SEO settings yet.</p>
          ) : (
            <div className="space-y-2">
              {pages.map((page) => (
                <div key={page.id} className="flex items-center gap-3 p-3 rounded-md border hover:bg-muted/50 transition-colors">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-sm">{page.title || page.page_path}</span>
                      <code className="text-xs bg-muted px-1.5 py-0.5 rounded">{page.page_path}</code>
                      {!page.is_active && <span className="text-xs bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded">Inactive</span>}
                      {page.is_active && <span className="text-xs bg-green-100 text-green-700 px-1.5 py-0.5 rounded">Active</span>}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5 truncate">{page.title || "Inherits global title"}</p>
                  </div>
                  <div className="flex gap-1 shrink-0">
                    <Button variant="ghost" size="sm" onClick={() => openEdit(page)}><Pencil className="h-3 w-3" /></Button>
                    <Button variant="ghost" size="sm" onClick={() => deletePage(page)} className="text-destructive hover:text-destructive"><Trash2 className="h-3 w-3" /></Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingPage ? "Edit" : "Add"} Page SEO</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <Label>Page Path *</Label>
                <Input value={form.page_path} onChange={(e) => setForm({ ...form, page_path: e.target.value })} placeholder="/about" disabled={!!editingPage} />
              </div>
              <div className="sm:col-span-2">
                <Label>Title</Label>
                <Input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Leave empty to inherit global title" />
                <p className="text-xs text-muted-foreground mt-1">{form.title.length}/70 chars recommended</p>
              </div>
              <div className="sm:col-span-2">
                <Label>Description</Label>
                <Textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Leave empty to inherit global description" className="min-h-[60px]" />
                <p className="text-xs text-muted-foreground mt-1">{form.description.length}/160 chars recommended</p>
              </div>
              <div className="sm:col-span-2">
                <Label>Keywords</Label>
                <Input value={form.keywords} onChange={(e) => setForm({ ...form, keywords: e.target.value })} placeholder="comma, separated, keywords" />
              </div>
              <div>
                <Label>OG Title</Label>
                <Input value={form.og_title} onChange={(e) => setForm({ ...form, og_title: e.target.value })} placeholder="Inherits from page title" />
              </div>
              <div>
                <Label>OG Image URL</Label>
                <Input value={form.og_image_url} onChange={(e) => setForm({ ...form, og_image_url: e.target.value })} placeholder="Inherits from global" />
              </div>
              <div className="sm:col-span-2">
                <Label>OG Description</Label>
                <Input value={form.og_description} onChange={(e) => setForm({ ...form, og_description: e.target.value })} placeholder="Inherits from page description" />
              </div>
              <div>
                <Label>Meta Robots</Label>
                <Input value={form.meta_robots} onChange={(e) => setForm({ ...form, meta_robots: e.target.value })} placeholder="index, follow (inherits global)" />
              </div>
              <div>
                <Label>Canonical URL</Label>
                <Input value={form.canonical_url} onChange={(e) => setForm({ ...form, canonical_url: e.target.value })} placeholder="Auto-generated if empty" />
              </div>
            </div>
            <div className="flex items-center gap-6">
              <div className="flex items-center gap-2">
                <Switch checked={form.is_active} onCheckedChange={(v) => setForm({ ...form, is_active: v })} />
                <Label>Active</Label>
              </div>
            </div>
            <Button onClick={savePage} disabled={saving} className="w-full">
              {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
              {editingPage ? "Update" : "Create"} Page SEO
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default PageSeoTab;

