"use client";

import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoSettings } from "@/hooks/useSeoSettings";
import { useSeoPages } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Save, Loader2, Map, Eye, Copy, ExternalLink } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const SitemapTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const { pages } = useSeoPages();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showPreview, setShowPreview] = useState(false);

  const [form, setForm] = useState({
    sitemap_enabled: true,
    sitemap_changefreq: "weekly",
    sitemap_priority: 0.8,
  });

  if (settings && !loaded) {
    const s = settings as Record<string, unknown>;
    setForm({
      sitemap_enabled: (s.sitemap_enabled as boolean) ?? true,
      sitemap_changefreq: (s.sitemap_changefreq as string) ?? "weekly",
      sitemap_priority: (s.sitemap_priority as number) ?? 0.8,
    });
    setLoaded(true);
  }

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await (supabase.from as Function)("seo_settings")
        .update(form)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Sitemap settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "sitemap", ...form });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  const baseUrl = settings?.canonical_url || window.location.origin;
  const sitemapPages = pages.filter((p) => (p as unknown as Record<string, unknown>).include_in_sitemap !== false && p.is_active);

  const generateSitemapXml = () => {
    const urls = sitemapPages.map((p) => {
      const pr = p as Record<string, unknown>;
      return `  <url>
    <loc>${baseUrl}${p.page_path}</loc>
    <changefreq>${(pr.changefreq as string) || form.sitemap_changefreq}</changefreq>
    <priority>${(pr.priority as number) ?? form.sitemap_priority}</priority>
  </url>`;
    }).join("\n");

    return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>`;
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2"><Map className="h-5 w-5" /> Sitemap Configuration</CardTitle>
          <CardDescription>Configure XML sitemap generation. Individual page settings are managed in the Page SEO tab.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-3">
            <Switch checked={form.sitemap_enabled} onCheckedChange={(v) => setForm({ ...form, sitemap_enabled: v })} />
            <Label>Enable Sitemap Generation</Label>
          </div>

          {form.sitemap_enabled && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <Label>Default Change Frequency</Label>
                <Select value={form.sitemap_changefreq} onValueChange={(v) => setForm({ ...form, sitemap_changefreq: v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="always">always</SelectItem>
                    <SelectItem value="hourly">hourly</SelectItem>
                    <SelectItem value="daily">daily</SelectItem>
                    <SelectItem value="weekly">weekly</SelectItem>
                    <SelectItem value="monthly">monthly</SelectItem>
                    <SelectItem value="yearly">yearly</SelectItem>
                    <SelectItem value="never">never</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Default Priority (0.0 - 1.0)</Label>
                <Select value={String(form.sitemap_priority)} onValueChange={(v) => setForm({ ...form, sitemap_priority: parseFloat(v) })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {[1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.3, 0.2, 0.1, 0.0].map((v) => (
                      <SelectItem key={v} value={String(v)}>{v.toFixed(1)}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}

          {form.sitemap_enabled && (
            <div className="rounded-md border p-3 bg-muted/50">
              <p className="text-sm font-medium mb-1">Pages in Sitemap: {sitemapPages.length}</p>
              <div className="flex flex-wrap gap-1">
                {sitemapPages.map((p) => (
                  <span key={p.id} className="text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">{p.page_path}</span>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {form.sitemap_enabled && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Sitemap Preview</CardTitle>
              <Button variant="outline" size="sm" onClick={() => setShowPreview(!showPreview)}>
                <Eye className="h-3 w-3 mr-1" /> {showPreview ? "Hide" : "Show"} Preview
              </Button>
            </div>
          </CardHeader>
          {showPreview && (
            <CardContent>
              <pre className="text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
                {generateSitemapXml()}
              </pre>
            </CardContent>
          )}
        </Card>
      )}

      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save Sitemap Settings
      </Button>

      {/* Live endpoint info */}
      <Card className="border-dashed bg-muted/30">
        <CardHeader className="pb-2 pt-4">
          <CardTitle className="text-sm">Dynamic Endpoint</CardTitle>
          <CardDescription className="text-xs">
            The sitemap is served live from this Supabase Edge Function URL and reflects your current page settings.
            Configure a rewrite rule on your production domain so <code className="bg-muted px-1 rounded text-xs">/sitemap.xml</code> proxies to this endpoint, or reference it directly.
          </CardDescription>
        </CardHeader>
        <CardContent className="pb-4 space-y-2">
          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
              {`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`}
            </code>
            <Button
              variant="ghost" size="icon" className="h-7 w-7 shrink-0"
              onClick={() => { navigator.clipboard.writeText(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`); toast.success("URL copied"); }}
            >
              <Copy className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" asChild>
              <a href={`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`} target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5" />
              </a>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default SitemapTab;

