import { createBrowserClient } from "@supabase/ssr";
import type { Database } from "./types";
import type { SupabaseClient } from "@supabase/supabase-js";

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

/**
 * Build a new browser Supabase client. Throws a clear error if the
 * required public env vars are missing — but only when actually called,
 * not at module-load time. This matters because `next build` evaluates
 * every module during the "Collecting page data" phase, and if this
 * file threw at module evaluation the entire build would fail on any
 * machine without NEXT_PUBLIC_SUPABASE_* set (CI, Docker layer caches,
 * etc.). The app is still unusable at runtime without these vars, but
 * the build succeeds and surfaces a clean error when the first request
 * hits an authenticated route.
 */
export function createClient(): SupabaseClient<Database> {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    throw new Error(
      "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in the hosting environment (Railway Variables tab for production, .env.local for local dev).",
    );
  }
  return createBrowserClient<Database>(SUPABASE_URL, SUPABASE_ANON_KEY);
}

// Lazy singleton. The first caller that touches any property on this
// proxy triggers createClient() — so at module-load time during
// `next build`, nothing throws and page data collection succeeds.
let _supabase: SupabaseClient<Database> | null = null;
function getClient(): SupabaseClient<Database> {
  if (!_supabase) _supabase = createClient();
  return _supabase;
}

export const supabase = new Proxy({} as SupabaseClient<Database>, {
  get(_target, prop) {
    const client = getClient();
    const value = Reflect.get(client, prop);
    // Bind methods so `this` stays correct for chained Supabase calls
    return typeof value === "function" ? value.bind(client) : value;
  },
});

// Compatibility shim: the real implementation now lives in browser.ts.
// After the Vite → Next.js 16 migration this file will be deleted. Every
// existing import of `@/integrations/supabase/client` continues to work
// because the exported `supabase` instance is identical in shape.
export { supabase } from "./browser";

