  if (!user) return;
  setRegenerating(true);
  try {
    const { data, error } = await supabase.rpc("generate_user_inbox_email" as never, { p_user_id: user.id } as never);
    if (error) throw error;
    await refreshProfile();
    toast.success(`Inbox regenerated: ${data}`);
  } catch (e: any) {
    toast.error(e.message || "Failed to regenerate inbox");
  } finally {
    setRegenerating(false);
  }
};

