"use client";

import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { Clock, Loader2, Save, Plus, Trash2 } from "lucide-react";

interface AvailabilitySettingsProps {
  userId: string;
  teamId?: string | null;
}

interface Slot {
  id?: string;
  start_time: string;
  end_time: string;
  is_booked: boolean;
}

function generateTimeOptions(): { value: string; label: string }[] {
  const options: { value: string; label: string }[] = [];
  for (let h = 0; h < 24; h++) {
    for (const m of [0, 30]) {
      const hh = String(h).padStart(2, "0");
      const mm = String(m).padStart(2, "0");
      const value = `${hh}:${mm}`;
      const hour12 = h === 0 ? 12 : h > 12 ? h - 12 : h;
      const ampm = h < 12 ? "AM" : "PM";
      const label = `${hour12}:${mm} ${ampm}`;
      options.push({ value, label });
    }
  }
  return options;
}

const TIME_OPTIONS = generateTimeOptions();

const AvailabilitySettings = ({ userId, teamId }: AvailabilitySettingsProps) => {
  const queryClient = useQueryClient();
  const [slots, setSlots] = useState<Slot[]>([]);

  const { data: existingSlots, isLoading } = useQuery({
    queryKey: ["availability_slots", userId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("availability_slots")
        .select("id, start_time, end_time, is_booked")
        .eq("user_id", userId)
        .order("start_time");
      if (error) throw error;
      return (data ?? []) as Slot[];
    },
    enabled: !!userId,
  });

  useEffect(() => {
    if (existingSlots) setSlots(existingSlots);
  }, [existingSlots]);

  const addSlot = () => {
    setSlots((prev) => [...prev, { start_time: "09:00", end_time: "17:00", is_booked: false }]);
  };

  const removeSlot = (idx: number) => {
    setSlots((prev) => prev.filter((_, i) => i !== idx));
  };

  const updateSlot = (idx: number, field: keyof Slot, value: string | boolean) => {
    setSlots((prev) => prev.map((s, i) => i === idx ? { ...s, [field]: value } : s));
  };

  const saveMutation = useMutation({
    mutationFn: async () => {
      const { error: delError } = await supabase
        .from("availability_slots")
        .delete()
        .eq("user_id", userId);
      if (delError) throw delError;

      if (slots.length === 0) return;

      const rows = slots.map((s) => ({
        user_id: userId,
        team_id: teamId || null,
        start_time: s.start_time,
        end_time: s.end_time,
        is_booked: s.is_booked,
      }));

      const { error: insertError } = await supabase
        .from("availability_slots")
        .insert(rows as never);
      if (insertError) throw insertError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["availability_slots", userId] });
      toast.success("Availability saved");
    },
    onError: () => {
      toast.error("Failed to save availability");
    },
  });

  if (isLoading) {
    return (
      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <Skeleton className="h-5 w-48" />
          <Skeleton className="h-4 w-72" />
        </CardHeader>
        <CardContent className="space-y-3">
          {[1, 2, 3].map((i) => <Skeleton key={i} className="h-10 w-full" />)}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-4">
        <CardTitle className="flex items-center gap-2 text-sm font-semibold">
          <Clock className="h-4 w-4 text-primary" />
          Interview Availability
        </CardTitle>
        <CardDescription>
          Add time slots when you're available for interviews.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {slots.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-4">No availability slots. Add one below.</p>
        ) : (
          <div className="space-y-2">
            {slots.map((slot, idx) => (
              <div key={idx} className="flex items-center gap-2">
                <Label className="text-xs w-10 shrink-0">From</Label>
                <Select value={slot.start_time} onValueChange={(v) => updateSlot(idx, "start_time", v)}>
                  <SelectTrigger className="h-8 text-xs flex-1"><SelectValue /></SelectTrigger>
                  <SelectContent className="max-h-[200px]">
                    {TIME_OPTIONS.map((o) => (
                      <SelectItem key={o.value} value={o.value} className="text-xs">{o.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Label className="text-xs w-6 shrink-0">To</Label>
                <Select value={slot.end_time} onValueChange={(v) => updateSlot(idx, "end_time", v)}>
                  <SelectTrigger className="h-8 text-xs flex-1"><SelectValue /></SelectTrigger>
                  <SelectContent className="max-h-[200px]">
                    {TIME_OPTIONS.filter((o) => o.value > slot.start_time).map((o) => (
                      <SelectItem key={o.value} value={o.value} className="text-xs">{o.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button variant="ghost" size="icon" className="h-8 w-8 shrink-0" onClick={() => removeSlot(idx)}>
                  <Trash2 className="h-3.5 w-3.5 text-destructive" />
                </Button>
              </div>
            ))}
          </div>
        )}

        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" className="gap-1.5" onClick={addSlot}>
            <Plus className="h-3.5 w-3.5" /> Add Slot
          </Button>
          <Button size="sm" className="gap-1.5" onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}>
            {saveMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
            Save
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

export default AvailabilitySettings;

