-- ============================================================================
-- 20260420000017_compat_view_triggers.sql
-- ----------------------------------------------------------------------------
-- Add INSTEAD OF INSERT/UPDATE/DELETE triggers to all compat views that
-- point at rankora_* tables. Without these triggers, inserts fail because:
--   1. account_id / app_id are NOT NULL in the underlying table
--   2. RLS policies require these fields for access control
--   3. The view doesn't expose or accept these fields
--
-- Each trigger resolves account_id from get_primary_account(auth.uid())
-- and app_id from get_app_id('rankora').
-- ============================================================================


-- ─── career_page_config → rankora_career_pages ──────────────────────────────

CREATE OR REPLACE FUNCTION career_page_config_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_career_pages (
    id, account_id, app_id, slug, company_name, logo_url, cover_image_url,
    brand_color, tagline, about, culture_title, culture_description,
    benefits_json, testimonials_json, social_links_json,
    meta_title, meta_description, is_published
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.slug, NEW.company_name, NEW.logo_url, NEW.cover_image_url,
    NEW.brand_color, NEW.tagline, NEW.about, NEW.culture_title,
    NEW.culture_description, NEW.benefits_json, NEW.testimonials_json,
    NEW.social_links_json, NEW.meta_title, NEW.meta_description,
    COALESCE(NEW.is_published, false)
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION career_page_config_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_career_pages SET
    slug = NEW.slug, company_name = NEW.company_name,
    logo_url = NEW.logo_url, cover_image_url = NEW.cover_image_url,
    brand_color = NEW.brand_color, tagline = NEW.tagline,
    about = NEW.about, culture_title = NEW.culture_title,
    culture_description = NEW.culture_description,
    benefits_json = NEW.benefits_json, testimonials_json = NEW.testimonials_json,
    social_links_json = NEW.social_links_json,
    meta_title = NEW.meta_title, meta_description = NEW.meta_description,
    is_published = NEW.is_published, updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS career_page_config_insert ON career_page_config;
CREATE TRIGGER career_page_config_insert
  INSTEAD OF INSERT ON career_page_config
  FOR EACH ROW EXECUTE FUNCTION career_page_config_insert_trigger();

DROP TRIGGER IF EXISTS career_page_config_update ON career_page_config;
CREATE TRIGGER career_page_config_update
  INSTEAD OF UPDATE ON career_page_config
  FOR EACH ROW EXECUTE FUNCTION career_page_config_update_trigger();


-- ─── tasks → rankora_tasks ──────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION tasks_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_tasks (
    id, account_id, app_id, job_id, candidate_id, assigned_to,
    title, description, due_date, priority, status, created_by
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.job_id, NEW.candidate_id, NEW.assigned_to,
    NEW.title, NEW.description, NEW.due_date, NEW.priority,
    COALESCE(NEW.status, 'pending'), COALESCE(NEW.created_by, auth.uid())
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION tasks_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_tasks SET
    title = NEW.title, description = NEW.description,
    due_date = NEW.due_date, priority = NEW.priority,
    status = NEW.status, assigned_to = NEW.assigned_to,
    updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS tasks_insert ON tasks;
CREATE TRIGGER tasks_insert
  INSTEAD OF INSERT ON tasks FOR EACH ROW EXECUTE FUNCTION tasks_insert_trigger();

DROP TRIGGER IF EXISTS tasks_update ON tasks;
CREATE TRIGGER tasks_update
  INSTEAD OF UPDATE ON tasks FOR EACH ROW EXECUTE FUNCTION tasks_update_trigger();


-- ─── candidate_notes → rankora_candidate_notes ──────────────────────────────

CREATE OR REPLACE FUNCTION candidate_notes_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_candidate_notes (
    id, account_id, app_id, resume_id, content, created_by
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.resume_id, NEW.content, COALESCE(NEW.created_by, auth.uid())
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION candidate_notes_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_candidate_notes SET
    content = NEW.content, updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS candidate_notes_insert ON candidate_notes;
CREATE TRIGGER candidate_notes_insert
  INSTEAD OF INSERT ON candidate_notes FOR EACH ROW EXECUTE FUNCTION candidate_notes_insert_trigger();

DROP TRIGGER IF EXISTS candidate_notes_update ON candidate_notes;
CREATE TRIGGER candidate_notes_update
  INSTEAD OF UPDATE ON candidate_notes FOR EACH ROW EXECUTE FUNCTION candidate_notes_update_trigger();


-- ─── candidate_tags → rankora_candidate_tags ────────────────────────────────

CREATE OR REPLACE FUNCTION candidate_tags_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_candidate_tags (
    id, account_id, app_id, resume_id, tag
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.resume_id, NEW.tag
  );
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS candidate_tags_insert ON candidate_tags;
CREATE TRIGGER candidate_tags_insert
  INSTEAD OF INSERT ON candidate_tags FOR EACH ROW EXECUTE FUNCTION candidate_tags_insert_trigger();


-- ─── api_keys → rankora_api_keys ────────────────────────────────────────────

CREATE OR REPLACE FUNCTION api_keys_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_api_keys (
    id, account_id, app_id, name, key_hash, prefix, scopes, created_by
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.name, NEW.key_hash, NEW.prefix, NEW.scopes,
    COALESCE(NEW.created_by, auth.uid())
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION api_keys_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_api_keys SET
    name = NEW.name, scopes = NEW.scopes,
    last_used_at = NEW.last_used_at, is_active = NEW.is_active,
    updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS api_keys_insert ON api_keys;
CREATE TRIGGER api_keys_insert
  INSTEAD OF INSERT ON api_keys FOR EACH ROW EXECUTE FUNCTION api_keys_insert_trigger();

DROP TRIGGER IF EXISTS api_keys_update ON api_keys;
CREATE TRIGGER api_keys_update
  INSTEAD OF UPDATE ON api_keys FOR EACH ROW EXECUTE FUNCTION api_keys_update_trigger();


-- ─── job_pipeline_stages → rankora_pipeline_stages ──────────────────────────

CREATE OR REPLACE FUNCTION pipeline_stages_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid; v_app_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, get_primary_account(auth.uid()));
  v_app_id := get_app_id('rankora');
  INSERT INTO rankora_pipeline_stages (
    id, account_id, app_id, job_id, name, position, color
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()), v_account_id, v_app_id,
    NEW.job_id, NEW.name, COALESCE(NEW.position, 0), NEW.color
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION pipeline_stages_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_pipeline_stages SET
    name = NEW.name, position = NEW.position, color = NEW.color,
    updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS pipeline_stages_insert ON job_pipeline_stages;
CREATE TRIGGER pipeline_stages_insert
  INSTEAD OF INSERT ON job_pipeline_stages FOR EACH ROW EXECUTE FUNCTION pipeline_stages_insert_trigger();

DROP TRIGGER IF EXISTS pipeline_stages_update ON job_pipeline_stages;
CREATE TRIGGER pipeline_stages_update
  INSTEAD OF UPDATE ON job_pipeline_stages FOR EACH ROW EXECUTE FUNCTION pipeline_stages_update_trigger();


-- ─── admin_audit_logs (insert only, no account scoping needed) ──────────────

CREATE OR REPLACE FUNCTION audit_logs_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  INSERT INTO audit_logs (
    id, user_id, action, entity_type, entity_id, metadata
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    COALESCE(NEW.admin_user_id, auth.uid()),
    NEW.action, NEW.entity_type, NEW.entity_id, NEW.details
  );
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS admin_audit_logs_insert ON admin_audit_logs;
CREATE TRIGGER admin_audit_logs_insert
  INSTEAD OF INSERT ON admin_audit_logs FOR EACH ROW EXECUTE FUNCTION audit_logs_insert_trigger();


-- ─── Also fix existing triggers to use SECURITY DEFINER ─────────────────────
-- The jobs/resumes/results triggers use SECURITY INVOKER which means the
-- INSERT into the underlying table is checked by RLS as the calling user.
-- Switch to SECURITY DEFINER so the trigger can bypass RLS (the view's
-- security_invoker=true already enforces access control at the view level).

CREATE OR REPLACE FUNCTION jobs_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid;
BEGIN
  v_account_id := COALESCE(NEW.account_id, NEW.team_id, get_primary_account(auth.uid()));
  INSERT INTO rankora_jobs (
    id, app_id, account_id, created_by,
    title, job_description, jd_analysis_json, dynamic_weights_json,
    scoring_weights, status, inbox_email, jd_embedding
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id,
    COALESCE(NEW.created_by, auth.uid()),
    NEW.title, NEW.job_description, NEW.jd_analysis_json, NEW.dynamic_weights_json,
    COALESCE(NEW.scoring_weights, '{"must": 0.6, "nice": 0.3, "optional": 0.1}'::jsonb),
    COALESCE(NEW.status, 'pending'),
    NEW.inbox_email, NEW.jd_embedding
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION jobs_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_jobs SET
    title = NEW.title, job_description = NEW.job_description,
    jd_analysis_json = NEW.jd_analysis_json,
    dynamic_weights_json = NEW.dynamic_weights_json,
    scoring_weights = NEW.scoring_weights,
    status = NEW.status, inbox_email = NEW.inbox_email,
    jd_embedding = NEW.jd_embedding, updated_at = now()
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION resumes_insert_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_account_id uuid;
BEGIN
  v_account_id := COALESCE(
    NEW.account_id,
    (SELECT account_id FROM rankora_jobs WHERE id = NEW.job_id),
    get_primary_account(auth.uid())
  );
  INSERT INTO rankora_resumes (
    id, app_id, account_id, job_id, created_by,
    filename, file_path, file_size_bytes,
    candidate_name, candidate_email, candidate_phone, candidate_location,
    parsed_json, parsed_text, embedding, status, source
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    get_app_id('rankora'),
    v_account_id, NEW.job_id,
    COALESCE(NEW.created_by, auth.uid()),
    NEW.filename, NEW.file_path, NEW.file_size_bytes,
    NEW.candidate_name, NEW.candidate_email, NEW.candidate_phone,
    NEW.candidate_location, NEW.parsed_json, NEW.parsed_text,
    NEW.embedding, COALESCE(NEW.status, 'pending'), NEW.source
  );
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION resumes_update_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE rankora_resumes SET
    filename = NEW.filename, file_path = NEW.file_path,
    file_size_bytes = NEW.file_size_bytes,
    candidate_name = NEW.candidate_name,
    candidate_email = NEW.candidate_email,
    candidate_phone = NEW.candidate_phone,
    candidate_location = NEW.candidate_location,
    parsed_json = NEW.parsed_json, parsed_text = NEW.parsed_text,
    embedding = NEW.embedding, status = NEW.status, source = NEW.source
  WHERE id = OLD.id;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION resumes_delete_trigger()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  DELETE FROM rankora_resumes WHERE id = OLD.id;
  RETURN OLD;
END; $$;

