const DodoBadge = ({ p }: { p: any }) => {
  const vr = verifyResults[p.dodo_product_id];
  if (!p.dodo_product_id) {
    return (
      <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[11px]" onClick={() => handleSyncToDodo(p)} disabled={saving}>
        <Link2 className="h-3 w-3 text-amber-500" />
        <span className="text-muted-foreground">Sync to Dodo</span>
      </Button>
    );
  }
  return (
    <Button
      variant="ghost"
      size="sm"
      className="h-6 px-2 gap-1 text-[11px]"
      onClick={() => handleVerify(p.id, p.dodo_product_id)}
      disabled={verifying === p.dodo_product_id}
    >
      {verifying === p.dodo_product_id ? (
        <Loader2 className="h-3 w-3 animate-spin" />
      ) : vr ? (
        vr.exists && vr.is_active ? <CheckCircle className="h-3 w-3 text-emerald-600" /> :
        vr.exists ? <AlertTriangle className="h-3 w-3 text-amber-500" /> :
        <AlertTriangle className="h-3 w-3 text-destructive" />
      ) : (
        <CheckCircle className="h-3 w-3 text-emerald-600" />
      )}
      <span>{vr ? (vr.exists && vr.is_active ? "Verified ✓" : vr.exists ? "Inactive on Dodo" : "Not found") : "Linked"}</span>
      <RefreshCw className="h-2.5 w-2.5 text-muted-foreground" />
    </Button>
  );
};

