// ── Insert application record ─────────────────────────────────────────
const { data: application, error: insertError } = await supabase
  .from("applications")
  .insert({
    id: applicantId,
    job_id: jobId,
    name: name.slice(0, 200),
    email: email.toLowerCase().slice(0, 254),
    phone: phone ? phone.slice(0, 50) : null,
    linkedin_url: linkedinUrl ? linkedinUrl.slice(0, 500) : null,
    resume_path: resumePath,
    resume_filename: resumeFilename,
    status: "pending",
    custom_fields: Object.keys(customFields).length > 0 ? customFields : null,
  })
  .select("id")
  .single();

if (insertError) {
  // Postgres unique violation — duplicate application for same job + email
  if (insertError.code === "23505") {
    return new Response(
      JSON.stringify({ error: "You have already applied for this position" }),
      {
        status: 409,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
  console.error("Application insert failed:", insertError.message);
  return new Response(
    JSON.stringify({ error: "Failed to submit application. Please try again." }),
    {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    }
  );
}

if (!application) {
  return new Response(
    JSON.stringify({ error: "Failed to submit application. Please try again." }),
    {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    }
  );
}

// ── Knockout evaluation ───────────────────────────────────────────────
// Only runs if we have custom field responses
if (Object.keys(customFields).length > 0) {
  try {
    const { data: knockoutFields } = await supabase
      .from("job_form_fields")
      .select("id, label, knockout_answer")
      .eq("job_id", jobId)
      .eq("is_knockout", true);

    if (knockoutFields && knockoutFields.length > 0) {
      let isKnocked = false;
      let knockReason = "";

      for (const kf of knockoutFields) {
        const candidateAnswer = customFields[kf.id];
        if (
          candidateAnswer !== undefined &&
          kf.knockout_answer !== null &&
          String(candidateAnswer).trim().toLowerCase() ===
            kf.knockout_answer.trim().toLowerCase()
        ) {
          isKnocked = true;
          knockReason = `Knockout: "${kf.label}" answer did not meet requirements`;
          break;
        }
      }

      if (isKnocked) {
        await supabase
          .from("applications")
          .update({
            auto_disqualified: true,
            disqualify_reason: knockReason,
            status: "rejected",
          })
          .eq("id", applicantId);
      }
    }
  } catch (knockErr) {
    // Non-fatal — don't block the response
    console.error("Knockout evaluation error:", knockErr);
  }
}

