"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Copy, Mail, Link2, Code, Check } from "lucide-react";
import FormBuilder from "@/components/FormBuilder";
import AutoAckSettings from "@/components/AutoAckSettings";
import JobDistributionPanel from "@/components/JobDistributionPanel";

interface JobSettingsTabProps {
  jobId: string;
  jobTitle: string;
  jobSlug?: string | null;
  inboxEmail?: string | null;
  teamId?: string | null;
  careerPageActive?: boolean;
  appUrl?: string;
}

/**
 * Unified settings tab for a single job. Replaces the old scattered config:
 * Applications tab (FormBuilder + AutoAck), Distribute tab, and inbox email
 * notice. Gives the user ONE place to configure every intake channel, every
 * form field, and every auto-reply for this job.
 */
export default function JobSettingsTab({
  jobId,
  jobTitle,
  jobSlug,
  inboxEmail,
  teamId,
  careerPageActive,
  appUrl,
}: JobSettingsTabProps) {
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  const baseUrl = appUrl ?? (typeof window !== "undefined" ? window.location.origin : "");
  const applyUrl = `${baseUrl}/apply/${jobId}`;
  const embedSnippet = `<iframe src="${applyUrl}" width="100%" height="800" frameborder="0" title="Apply for ${jobTitle}"></iframe>`;

  const copy = async (value: string, key: string) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopiedKey(key);
      toast.success("Copied to clipboard");
      setTimeout(() => setCopiedKey(null), 1500);
    } catch {
      toast.error("Failed to copy");
    }
  };

  return (
    <div className="space-y-6">
      {/* ── Intake channels ─────────────────────────────────────────────── */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Link2 className="h-4 w-4 text-primary" />
            Intake channels
          </CardTitle>
          <p className="text-xs text-muted-foreground">
            How candidates reach this job. All inbound resumes get AI-ranked automatically.
          </p>
        </CardHeader>
        <CardContent className="space-y-5">
          {/* Public apply link */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">Public apply link</Label>
            <div className="flex items-center gap-2">
              <Input
                value={applyUrl}
                readOnly
                className="h-8 text-xs font-mono"
                onClick={(e) => (e.target as HTMLInputElement).select()}
              />
              <Button
                variant="outline"
                size="sm"
                className="h-8 shrink-0 gap-1.5"
                onClick={() => copy(applyUrl, "apply")}
              >
                {copiedKey === "apply" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
                Copy
              </Button>
            </div>
            <p className="text-[11px] text-muted-foreground">
              Share this link anywhere. Candidates fill the form below and their resumes land in the Candidates tab, scored.
            </p>
          </div>

          {/* Resume inbox email */}
          {inboxEmail && (
            <div className="space-y-1.5">
              <Label className="text-xs font-medium flex items-center gap-1.5">
                <Mail className="h-3.5 w-3.5" />
                Resume inbox email
              </Label>
              <div className="flex items-center gap-2">
                <Input
                  value={inboxEmail}
                  readOnly
                  className="h-8 text-xs font-mono"
                  onClick={(e) => (e.target as HTMLInputElement).select()}
                />
                <Button
                  variant="outline"
                  size="sm"
                  className="h-8 shrink-0 gap-1.5"
                  onClick={() => copy(inboxEmail, "inbox")}
                >
                  {copiedKey === "inbox" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
                  Copy
                </Button>
              </div>
              <p className="text-[11px] text-muted-foreground">
                Forward any candidate email to this address — resumes extracted automatically.
              </p>
            </div>
          )}

          {/* Embed snippet */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium flex items-center gap-1.5">
              <Code className="h-3.5 w-3.5" />
              Embed on your website
            </Label>
            <div className="flex items-start gap-2">
              <Textarea
                value={embedSnippet}
                readOnly
                rows={2}
                className="text-[11px] font-mono resize-none"
                onClick={(e) => (e.target as HTMLTextAreaElement).select()}
              />
              <Button
                variant="outline"
                size="sm"
                className="h-8 shrink-0 gap-1.5"
                onClick={() => copy(embedSnippet, "embed")}
              >
                {copiedKey === "embed" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
                Copy
              </Button>
            </div>
            <p className="text-[11px] text-muted-foreground">
              Paste this iframe on your careers page, landing page, or any public site.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* ── Distribution (LinkedIn, Indeed, X, Google Jobs) ─────────────── */}
      <JobDistributionPanel
        jobId={jobId}
        jobTitle={jobTitle}
        slug={jobSlug ?? null}
        teamId={teamId ?? null}
        careerPageActive={careerPageActive ?? false}
      />

      {/* ── Application form builder ────────────────────────────────────── */}
      <FormBuilder jobId={jobId} />

      {/* ── Auto-acknowledgement email ──────────────────────────────────── */}
      <AutoAckSettings jobId={jobId} />
    </div>
  );
}

